// Observe the unmodified short form with actual independent tabs and pagehide.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Only the authorized Linux Actions origin');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE),git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex');
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],captures:[],external:[],mutations:[],limits:['Four EN/UR320/1280 Chromium flows with actual independent tabs, DOM input and real navigation pagehide. No synthesized pagehide or app/storage method replacement.','Only anonymous fixture strings in disposable browser storage. No actual candidates, external requests, messages or submissions.','Only first-name field components are captured. No whole-page, all-language, physical-device or screen-reader certificate.']};
assert.equal(report.checkout,report.head);assert.equal(git('merge-base',report.head,report.base).toString().trim(),report.base);const old=git('ls-tree','-r',report.base).toString().trim().split('\n');assert.equal(old.length,518);for(const row of old){const [,p]=row.split('\t');if(p!=='docs/primserv-roadmap.md')assert.deepEqual(git('show',report.head+':'+p),git('show',report.base+':'+p),p);}report.oldNonCanonicalUnchanged=517;
for(const {path:p}of inventory(artifact)){const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',report.head+':'+source));report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact:b.equals(git('show',report.base+':'+source))};}assert.equal(Object.keys(report.files).length,317);assert.equal(Object.values(report.files).filter(x=>x.publishedExact).length,316);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-two-tab-baseline-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/',key='citronex_screening_application_v17';let browser;
async function stored(page){return page.evaluate(k=>JSON.parse(localStorage.getItem(k)),key);}
async function capture(page,width,lang,stage){await page.evaluate(()=>document.fonts.ready);const field=page.locator('#firstName').locator('..');await field.scrollIntoViewIfNeeded();const dom=await field.evaluate(n=>({text:n.innerText,value:n.querySelector('input').value,focused:document.activeElement===n.querySelector('input'),visible:n.checkVisibility(),fit:n.scrollWidth<=n.clientWidth+1,lang:document.documentElement.lang,pageFits:document.documentElement.scrollWidth<=innerWidth+1}));assert(dom.visible&&dom.fit&&dom.pageFits&&dom.lang===lang);const file=`two-tab-${width}-${lang}-${stage}.png`;await field.screenshot({path:join(reportDir,file)});report.captures.push({file,width,lang,stage,sha256:sha(await readFile(join(reportDir,file))),dom,originalPixels:true});}
async function resume(page){await page.locator('[data-action="resume"]').focus();await page.keyboard.press('Enter');}
async function run(width,lang){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);await ctx.route('**/*',route=>{const r=route.request(),u=new URL(r.url());if(!['GET','HEAD'].includes(r.method())){report.mutations.push({method:r.method(),path:u.pathname,blocked:true});return route.abort();}if(u.origin!==new URL(base).origin){report.external.push({host:u.hostname,path:u.pathname,blocked:true});return route.abort();}return route.continue();});const a=await ctx.newPage(),errors=[];ctx.on('page',p=>p.on('pageerror',e=>errors.push(e.message)));a.on('pageerror',e=>errors.push(e.message));
 try{
  const entry=base+'apply/?lang='+lang;await a.goto(entry);await a.locator('#languageSearch').fill(lang);await a.locator(`[data-language="${lang}"]`).click();await a.locator('[data-recruiter="yana"]').click();await a.locator('#firstName').fill('OLDER FIXTURE');const older=await stored(a);assert.equal(older.data.firstName,'OLDER FIXTURE');assert.equal(typeof older.id,'string');await a.evaluate(()=>localStorage.setItem('two-tab-unrelated','KEEP'));await capture(a,width,lang,'older-a');
  const b=await ctx.newPage();await b.goto(entry);await resume(b);assert.equal(await b.locator('#firstName').inputValue(),'OLDER FIXTURE');await b.locator('#firstName').fill('LATEST FIXTURE');const latest=await stored(b);assert.equal(latest.data.firstName,'LATEST FIXTURE');assert.equal(latest.id,older.id);assert.equal(latest.routeKey,older.routeKey);assert.equal(latest.language,lang);assert.equal(latest.step,1);await capture(b,width,lang,'latest-b');
  // Real navigation fires the older tab's existing pagehide autosave.
  await a.goto('about:blank');const overwritten=await stored(b);assert.equal(overwritten.data.firstName,'OLDER FIXTURE');assert.deepEqual(overwritten.data,older.data);assert.equal(overwritten.id,latest.id);assert.equal(await b.locator('#firstName').inputValue(),'LATEST FIXTURE');assert.equal(await b.evaluate(()=>localStorage.getItem('two-tab-unrelated')),'KEEP');
  const returned=await ctx.newPage();await returned.goto(entry);await resume(returned);assert.equal(await returned.locator('#firstName').inputValue(),'OLDER FIXTURE');await capture(returned,width,lang,'returned-older');assert.deepEqual(errors,[]);
  report.rows.push({width,lang,status:'observed',actualTabAPagehideNavigation:true,older,newerPersistedBeforePagehide:latest,persistedAfterOldPagehide:overwritten,newerTabLiveAnswer:'LATEST FIXTURE',returnedSavedAnswer:'OLDER FIXTURE',newerPersistedAnswerLost:true,idRouteLanguageStepPreserved:true,unrelatedKeyPreserved:true,noDelivery:true});
 }catch(e){report.failedCase??={width,lang,message:e.message,errors};await a.screenshot({path:join(reportDir,`failure-two-tab-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
try{await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();for(const width of [320,1280])for(const lang of ['en','ur'])await run(width,lang);assert.equal(report.rows.length,4);assert.equal(report.captures.length,12);assert.deepEqual(report.external,[]);assert.deepEqual(report.mutations,[]);report.applicationDeliveryAttempts=0;report.status='OBSERVED_4_ACTUAL_OLDER_TAB_PAGEHIDE_OVERWRITES_OF_NEWER_SAVED_ANSWER';}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
